namespace ghidra.framework.options;






using generic.theme.GThemeDefaults.Colors;

public class ErrorPropertyEditor : PropertyEditorSupport {
	private JLabel errorLabel;
	private object editorValue;

	public ErrorPropertyEditor(string errorMessage, object value) {
		editorValue = value;
		string message = errorMessage;
		if (editorValue != null) {
			message += " - value: " + value.toString();
		}

		// Use native java JLabel because we can't use docking widgets here
		errorLabel = new JLabel(message);
		errorLabel.setForeground(Messages.ERROR);
		errorLabel.putClientProperty("html.disable", true);
	}

	/* @Override */
	public JComponent getCustomEditor() {
		return errorLabel;
	}

	/* @Override */
	public bool supportsCustomEditor() {
		return true;
	}
}
